sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from authoring import finish,ref,step,paragraph
finish('nl-versus-ul',
 id='TCS-6533',title='NL versus UL',area='Computational complexity',criterion='resources',question_type='yes_no',
 formal='Is NL=UL? Equivalently, is there a single nondeterministic Turing machine that decides directed s–t reachability using O(log N) work space and polynomial time, has exactly one accepting computation on every reachable instance, and has no accepting computation on every unreachable instance, where N is the explicit input length?',
 definitions='An input consists of a finite directed graph with labelled vertices and explicitly listed edges, together with vertices s,t. Reachability asks whether a directed path from s to t exists; the length-zero path is allowed when s=t. A machine has a read-only two-way input tape, O(log(N+2)) read/write work-tape cells over a fixed finite alphabet, and a fixed finite nondeterministic transition relation. Every computation branch must halt within a polynomial in N. NL permits any positive number of accepting branches on yes inputs; UL permits exactly one. On no inputs both classes require zero accepting branches. A branch is a sequence of transition choices, not merely its endpoint or output. Rejecting branches need not be unique. Machines are uniform finite programs without advice, randomness, oracle access or additional catalytic storage. The equality asks whether every NL language has some equivalent UL machine; it does not require a computable compiler converting descriptions of arbitrary machines. Directed reachability is NL-complete under deterministic logspace reductions, so its UL membership suffices.',
 answer_criterion='Prove a uniform O(log N)-space unambiguous algorithm for all directed reachability inputs, or prove that some NL language is not in UL. Any positive construction must remain unambiguous on every input without assuming that the supplied graph itself has a unique path. A polynomial-time algorithm using O((log N)^{3/2}) space, nonuniform advice, catalytic memory, or an unproved hardness hypothesis is progress rather than a solution.',
 context=[
 paragraph('A nondeterministic reachability algorithm can guess the next vertex of a path, checking each edge as it goes. It needs only a current vertex and a step counter, so logarithmic memory suffices. The difficulty is that a graph can offer many successful sequences of guesses. An unambiguous algorithm must retain the ability to recognize a path while allowing only one successful computation.'),
 paragraph('This restriction is weaker than determinism. The machine may still branch many times and have many rejecting computations. On a reachable graph, only one complete branch may accept. Consequently, NL=UL would explain something about the source of nondeterministic power without establishing L=NL. A proof that NL≠UL would, however, also separate deterministic and nondeterministic logspace, since L⊆UL⊆NL.'),
 paragraph('One approach is to assign positive integer weights to edges so that every reachable ordered pair has a unique minimum-weight path. Reinhardt and Allender show how such min-isolating weights support an unambiguous reachability algorithm. If the weights are polynomially bounded and can be generated in deterministic logspace from the graph, the resulting memory use remains logarithmic. Randomly choosing suitable weights can give isolation, but does not provide a uniform deterministic construction.','nonuniform'),
 paragraph('Reinhardt and Allender also prove NL/poly=UL/poly. Here a polynomial-length advice string may depend on the input length and be shared by every input of that length, without any requirement that the string be generated efficiently. This is evidence that isolation is possible in a broad nonuniform sense. Removing the advice is essential to the ordinary NL=UL question.','nonuniform'),
 paragraph('The strongest checked unconditional general simulation uses more than logarithmic memory. Van Melkebeek and Prakriya give an unambiguous polynomial-time simulation of NL using O((log N)^{3/2}) space. Their work reduces the randomness and weight-description costs of isolation. The remaining square-root-of-logarithm factor is small numerically, but it is an unbounded factor in the resource defining the target class.','space'),
 paragraph('The inherited 2025 paper by Doron, Pyne, Tell and Williams develops new hardness-versus-randomness tools for isolation. Its main conditional unambiguity theorem concerns the linear-space analogue NSPACE[n]⊆USPACE[O(n)], under uniform circuit lower bounds with specified oracle access. The March 2026 Pyne–Tell survey gives a refined version. These assumptions are unproved, and the linear-space conclusion should not be reported as an unconditional logspace equality.','winwin'),
 paragraph('A February 2026 revision by Arvind, Chakraborty and Datta gives reachability algorithms in a catalytic model with UL oracle access. Catalytic computation permits extra memory initially containing arbitrary data, provided that the data are restored at the end. This is an interesting way to use storage, but it supplies resources absent from a plain UL machine. The headline about derandomizing isolation therefore does not resolve this card.','catalytic'),
 paragraph('Hoza proves a new limitation in July 2026. Suppose one weight assignment must work for every layered graph of given width w and length ℓ, without examining which edges are actually present. Such an oblivious min-isolating assignment requires weights of magnitude 2^{Ω(log w·log ℓ)}, so polynomially bounded universal weights cannot solve the general problem by this route. This restriction does not cover assignments that depend on the actual graph or other unambiguous algorithms.','oblivious'),
 paragraph('A solution would determine whether many successful paths are ever intrinsically necessary when computation has only logarithmic memory. It would also clarify how much information must be retained to select a unique witness from a large implicitly represented family. The challenge is not to name a canonical path mathematically, but to recognize one with the required uniqueness guarantee and very little working storage.')],
 why='Determine whether the multiplicity of accepting computations adds power to logarithmic-space computation.',
 importance=dict(score=95,method='editorial',assessed_on='2026-09-11',reason='A basic class equality tying directed reachability, isolation, pseudorandomness and the structure of low-memory witnesses.'),
 progress=[
 step('1997–2000','Reinhardt–Allender show that min-isolation supports unambiguous reachability and prove the nonuniform equality NL/poly=UL/poly.','nonuniform'),
 step('2017–2019','Van Melkebeek–Prakriya obtain a polynomial-time unambiguous simulation using O((log N)^{3/2}) space; CCC 2017 and SICOMP 2019.','space'),
 step('2025-06-18','Doron–Pyne–Tell–Williams derive linear-space unambiguity from substantially weakened but still unproved uniform circuit lower bounds.','winwin'),
 step('2026-02-06','Arvind–Chakraborty–Datta’s revised catalytic isolation result uses extra restorable memory and UL oracle access.','catalytic'),
 step('2026-03-30','Pyne–Tell survey recent isolation results, distinguishing the classical conditional NL=UL theorem from newer conditional linear-space simulations.','survey'),
 step('2026-07-23','Hoza proves that deterministic oblivious min-isolation for all layered digraphs requires quasipolynomial-size weights in the general parameter regime.','oblivious')],
 references=[
 ref('nonuniform','Making Nondeterminism Unambiguous','Klaus Reinhardt; Eric Allender',2000,'https://people.cs.rutgers.edu/~allender/papers/nlul.pdf','FOCS 1997 precursor; manuscript 31 March 1999; SIAM Journal on Computing 29(4), 1118–1131, 2000; min-isolation and NL/poly=UL/poly'),
 ref('space','Derandomizing Isolation in Space-Bounded Settings','Dieter van Melkebeek; Gautam Prakriya',2019,'https://pages.cs.wisc.edu/~dieter/Papers/r-ul-sicomp.pdf','CCC 2017 precursor; SIAM Journal on Computing 48(3), 979–1021, published electronically 9 May 2019; polynomial time and O(log^{3/2} N) unambiguous space'),
 ref('winwin','When Connectivity Is Hard, Random Walks Are Easy With Non-Determinism','Dean Doron; Edward Pyne; Roei Tell; Ryan Williams',2025,'https://eccc.weizmann.ac.il/report/2025/077/download','18 June 2025; Theorem 6 specifies the conditional linear-space simulation; Theorem 4.11 develops isolation tools; inherited reference'),
 ref('survey','Using Hardness vs Randomness to Design Low-Space Algorithms','Edward Pyne; Roei Tell',2026,'https://eccc.weizmann.ac.il/report/2026/045/','Manuscript dated 30 March 2026; Bulletin of the EATCS 148; Section 3.4.3, Theorems 3.12–3.13 distinguish logspace equality and linear-space simulation'),
 ref('catalytic','Derandomizing Isolation In Catalytic Logspace','V. Arvind; Srijan Chakraborty; Samir Datta',2026,'https://arxiv.org/abs/2512.09374','First posted 10 December 2025; checked v3, 6 February 2026; reachability in a polynomial-time catalytic model with O(log² n) catalytic bits and UL oracle access'),
 ref('oblivious','Deterministic, Oblivious Isolation for Space-Bounded Computation Requires Large Weights','William M. Hoza',2026,'https://eccc.weizmann.ac.il/report/2026/124/','Manuscript 23 July 2026; Sections 1.1–1.3 define graph-dependent and oblivious isolation; lower bound concerns a single weight function for every graph of given width and length')],
 status='source_open',status_note='The checked general unconditional simulation still uses O(log^{3/2} N) space. The 2025–2026 hardness-based results remain conditional, catalytic results use additional resources, and Hoza’s July 2026 lower bound excludes only oblivious isolation. No settlement of uniform NL=UL found through 11 September 2026.',formulation_reviewed_on='2026-09-11')
